import type { OperationalMetrics } from "./metrics.js";

export function renderOperationalReport(metrics: OperationalMetrics): string {
  return [
    "# Operational Report",
    "",
    `**Period:** ${metrics.period}`,
    "",
    "## Metrics",
    "",
    `- Successful runs: ${String(metrics.runsSucceeded)}`,
    `- Failed runs: ${String(metrics.runsFailed)}`,
    `- Median attempt latency (ms): ${String(metrics.medianLatencyMs)}`,
    `- Approval backlog: ${String(metrics.approvalBacklog)}`,
    "",
    "_Generated by the scheduled reporting agent example (fixture metrics)._",
    "",
  ].join("\n");
}
